                $imp{$alias} = $path;
            } elsif ($line =~ /^"([^"]+)"/) {
                my $path = $1;
                my $alias = (split /\//, $path)[-1];
                $imp{$alias} = $path;
            }
        }
    }
    while ($src =~ /import\s+(?:(\w+|\.)\s+)?"([^"]+)"/g) {
        my ($alias, $path) = ($1, $2);
        $alias = (split /\//, $path)[-1] unless defined $alias && $alias ne "";
        $imp{$alias} = $path;
    }
    return \%imp;
}

