sub strip_comments_strings {
    my ($src) = @_;
    # replace comments and strings with spaces to avoid false matches, keep newlines
    $src =~ s{/\*.*?\*/}{ " " x length($&) }gse;
    $src =~ s{//[^\n]*}{}g;
    $src =~ s/"(?:\\.|[^"\\])*"/""/g;
    $src =~ s/`[^`]*`/``/g;
    $src =~ s/'(?:\\.|[^'\\])*'/''/g;
    return $src;
