                unless (exists $alias_to_ipath{$alias} && exists $pkg_funcs{$alias_to_ipath{$alias}}{$name}) {
                    add_hit("METHOD:" . $ms[0]{key}, $rel, func_at_pos($src, $pos));
                }
            }
        }
    }

    # Unqualified same-package calls
    if (exists $pkg_funcs{$ipath}) {
        while ($src =~ /(?:^|[^.\w])([A-Za-z_][A-Za-z0-9_]*)\s*\(/g) {
            my $name = $1;
            my $start = $-[1];
            next unless exists $pkg_funcs{$ipath}{$name};
            my $pre = substr($src, $start > 30 ? $start-30 : 0, $start > 30 ? 30 : $start);
            next if $pre =~ /func\s+$/;
            next if $pre =~ /func\s+\([^)]*\)\s*$/;
            add_hit($pkg_funcs{$ipath}{$name}{key}, $rel, func_at_pos($src, $start));
        }
    }
}

print "\n=== TOP package-level funcs by call sites (incl tests) ===\n";
my @pkg_keys = grep { !/^METHOD:/ } keys %sites;
my @sorted = sort { $sites{$b} <=> $sites{$a} } @pkg_keys;
for my $i (0..39) {
    last if $i > $#sorted;
    my $k = $sorted[$i];
    my $d = $decl_by_key{$k};
    printf "%4d sites  %3d files  %3d funcs  %-28s  %s\n",
        $sites{$k} // 0,
        count_hash($files{$k}),
        count_hash($funcs{$k}),
        $d->{name},
        $d->{file};
}

print "\n=== TOP unique-name methods by .Name( sites (incl tests) ===\n";
my @meth_keys = grep { /^METHOD:/ } keys %sites;
@sorted = sort { $sites{$b} <=> $sites{$a} } @meth_keys;
for my $i (0..19) {
    last if $i > $#sorted;
    my $k = $sorted[$i];
    my $real = $k; $real =~ s/^METHOD://;
    my $d = $decl_by_key{$real};
    printf "%4d sites  %3d files  %3d funcs  %s.%s  %s\n",
        $sites{$k} // 0,
        count_hash($files{$k}),
        count_hash($funcs{$k}),
        $d->{recv_type}, $d->{name},
        $d->{file};
}

print "\n=== TOP by unique calling functions ===\n";
@sorted = sort { count_hash($funcs{$b}) <=> count_hash($funcs{$a}) } @pkg_keys;
for my $i (0..19) {
    last if $i > $#sorted;
    my $k = $sorted[$i];
    my $d = $decl_by_key{$k};
    printf "%3d funcs  %4d sites  %-28s  %s\n",
        count_hash($funcs{$k}), $sites{$k}, $d->{name}, $d->{file};
}

print "\n=== Ambiguous package-level names (multiple decls) ===\n";
for my $n (sort keys %name_to_pkgfuncs) {
    my $c = scalar @{$name_to_pkgfuncs{$n}};
    print "$n: $c\n" if $c > 1;
}

print "\n=== Ambiguous method names (skipped unless unique) ===\n";
for my $n (sort keys %methods_by_name) {
    my $c = scalar @{$methods_by_name{$n}};
    print "$n: $c\n" if $c > 1;
}

print "\n=== Zero-site exported package funcs ===\n";
my $zero = 0;
for my $d (@decls) {
    next if $d->{is_method};
    next unless $d->{exported};
    next if $sites{$d->{key}};
    print $d->{name}, "  ", $d->{file}, "\n";
    $zero++;
}
print "(count $zero)\n";
ENDPL
