#!/usr/bin/env perl
use strict;
use warnings;

my $ROOT = "/bench/repo";
open my $lf, "<", "/tmp/gofiles.txt" or die $!;
my @all_go = grep { chomp; 1 } <$lf>;
close $lf;

sub read_file {
    my ($p) = @_;
    open my $fh, "<", $p or die "open $p: $!";
    local $/;
    return <$fh>;
}

# Collect decls
my @decls;
my %name_count;
for my $file (@all_go) {
    next unless $file =~ m{/internal/};
    next if $file =~ /_test\.go$/;
    my $src = read_file($file);
    my $rel = $file; $rel =~ s{^\Q$ROOT\E/}{};
    while ($src =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/mg) {
        my ($recv, $name) = ($1 // "", $2);
        $recv =~ s/^\s+|\s+$//g;
        next if $name eq "init";
        my $recv_type = "";
        if ($recv) {
            $recv_type = $recv;
            $recv_type =~ s/^\w+\s+//;
            $recv_type =~ s/^\*//;
        }
        push @decls, { name => $name, recv => $recv, recv_type => $recv_type, file => $rel };
        $name_count{$name}++;
    }
}

print "Unique names: ", scalar(grep { $name_count{$_} == 1 } keys %name_count), "\n";
print "Ambiguous names: ", scalar(grep { $name_count{$_} > 1 } keys %name_count), "\n";

# Load all file contents once
my %contents;
for my $file (@all_go) {
    $contents{$file} = read_file($file);
}

# For each unique name, count Name( occurrences
my @rows;
for my $d (@decls) {
    my $name = $d->{name};
    next unless $name_count{$name} == 1;
    my $re = qr/(?<![A-Za-z0-9_])\Q$name\E\s*\(/;
    my $all = 0; my $prod = 0; my $test = 0;
    my %all_files; my %prod_files;
    my $decl_hits = 0;
    for my $file (@all_go) {
        my $src = $contents{$file};
        my $n = 0;
        $n++ while $src =~ /$re/g;
        next unless $n;
        # subtract declaration in the decl file
        if ($file =~ /\Q$d->{file}\E$/) {
            # count how many are func decls
            my $decls_here = 0;
            $decls_here++ while $src =~ /^func\s+(?:\([^)]+\)\s+)?\Q$name\E\s*\(/mg;
            $n -= $decls_here;
            $decl_hits += $decls_here;
        }
        next unless $n > 0;
        $all += $n;
        $all_files{$file} = $n;
        if ($file =~ /_test\.go$/) {
            $test += $n;
        } else {
            $prod += $n;
            $prod_files{$file} = $n;
        }
    }
    push @rows, {
        %$d,
        all => $all,
        prod => $prod,
        test => $test,
        all_files => scalar(keys %all_files),
        prod_files => scalar(keys %prod_files),
    };
}

print "\n=== TOP unique-name symbols by ALL call sites (incl tests) ===\n";
my @sorted = sort { $b->{all} <=> $a->{all} || $b->{prod} <=> $a->{prod} } @rows;
for my $i (0..40) {
    last if $i > $#sorted;
    my $r = $sorted[$i];
    next if $r->{all} < 3;
    my $sym = $r->{recv_type} ? "$r->{recv_type}.$r->{name}" : $r->{name};
    printf "%4d all (%2d files)  %3d prod (%2d files)  %3d test  %-36s  %s\n",
        $r->{all}, $r->{all_files}, $r->{prod}, $r->{prod_files}, $r->{test},
        $sym, $r->{file};
}

print "\n=== TOP unique-name symbols by PROD call sites ===\n";
@sorted = sort { $b->{prod} <=> $a->{prod} || $b->{all} <=> $a->{all} } @rows;
for my $i (0..25) {
    last if $i > $#sorted;
    my $r = $sorted[$i];
    next if $r->{prod} < 2;
    my $sym = $r->{recv_type} ? "$r->{recv_type}.$r->{name}" : $r->{name};
    printf "%4d prod (%2d files)  %3d all  %-36s  %s\n",
        $r->{prod}, $r->{prod_files}, $r->{all}, $sym, $r->{file};
}

print "\n=== Ambiguous names (for reference) ===\n";
for my $n (sort { $name_count{$b} <=> $name_count{$a} } keys %name_count) {
    print "$n: $name_count{$n}\n" if $name_count{$n} > 1;
}
ENDPL
