cat > /tmp/callers.pl << 'ENDPL'
#!/usr/bin/env perl
use strict;
use warnings;

my $ROOT = "/bench/repo";
open my $lf, "<", "/tmp/gofiles.txt" or die $!;
my @all_go = grep { chomp; 1 } <$lf>;
close $lf;

sub read_file {
    my ($p) = @_;
    open my $fh, "<", $p or die $!;
    local $/; return <$fh>;
}

# For a given unique name, find enclosing func for each call
sub analyze {
    my ($name, $is_method_hint) = @_;
    my $re = qr/(?<![A-Za-z0-9_])\Q$name\E\s*\(/;
    my %callers_all;
    my %callers_prod;
    my $sites_all = 0;
    my $sites_prod = 0;
    for my $file (@all_go) {
        my $src = read_file($file);
        my $rel = $file; $rel =~ s{^\Q$ROOT\E/}{};
        my $is_test = ($file =~ /_test\.go$/) ? 1 : 0;

        # find all func decl positions
        my @funcs;
        while ($src =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/mg) {
            push @funcs, { pos => $-[0], name => ($1 ? do { my $r=$1; $r=~s/^\s+|\s+$//g; $r=~s/^\w+\s+//; $r=~s/^\*//; "$r.$2" } : $2) };
        }

        pos($src) = 0;
        while ($src =~ /$re/g) {
            my $pos = $-[0];
            # skip declaration
            my $pre = substr($src, $pos > 40 ? $pos-40 : 0, $pos > 40 ? 40 : $pos);
            next if $pre =~ /func\s+$/;
            next if $pre =~ /func\s+\([^)]*\)\s*$/;
            # skip comments roughly: if line starts with //
            my $line_start = rindex(substr($src, 0, $pos), "\n") + 1;
            my $line = substr($src, $line_start, $pos - $line_start);
            next if $line =~ m{^\s*//};

            my $caller = "<pkg>";
            for my $f (@funcs) {
                last if $f->{pos} > $pos;
                $caller = $f->{name};
            }
            my $key = "$rel:$caller";
            $callers_all{$key}++;
            $sites_all++;
            unless ($is_test) {
                $callers_prod{$key}++;
                $sites_prod++;
            }
        }
    }
    return {
        name => $name,
        sites_all => $sites_all,
        callers_all => scalar(keys %callers_all),
        sites_prod => $sites_prod,
        callers_prod => scalar(keys %callers_prod),
        caller_list_prod => [sort keys %callers_prod],
        caller_list_all => [sort keys %callers_all],
    };
}

my @names = qw(
    CompileToStatement NewEngine NewSchema addArg GenUUID
    jsonArrayExpr renderChildren getConstValue Field
    DefaultEngine AppendConditions getIdentName ConvertStringToInt32
    parse NewService qualifyColumn buildCondition
);

for my $n (@names) {
    my $r = analyze($n);
    printf "%-24s  sites %3d/%-2d  callers %3d/%-2d  (all/prod)\n",
        $n, $r->{sites_all}, $r->{sites_prod}, $r->{callers_all}, $r->{callers_prod};
}

print "\n=== addArg prod callers ===\n";
print "$_\n" for @{analyze("addArg")->{caller_list_prod}};
print "\n=== Field prod callers ===\n";
print "$_\n" for @{analyze("Field")->{caller_list_prod}};
print "\n=== CompileToStatement all callers ===\n";
print "$_\n" for @{analyze("CompileToStatement")->{caller_list_all}};
print "\n=== NewEngine all callers ===\n";
print "$_\n" for @{analyze("NewEngine")->{caller_list_all}};
print "\n=== GenUUID all callers ===\n";
print "$_\n" for @{analyze("GenUUID")->{caller_list_all}};
ENDPL
