perl -e '
open F, "/bench/repo/internal/filter/render.go";
@lines = <F>;
my @funcs;
for my $i (0..$#lines) {
  if ($lines[$i] =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
    my $recv = $1 // "";
    my $name = $2;
    $recv =~ s/^\s+|\s+$//g;
    my $t = $recv; $t =~ s/^\w+\s+//; $t =~ s/^\*//;
    my $full = $recv ? "$t.$name" : $name;
    push @funcs, [$i+1, $full];
  }
}
my %callers;
for my $i (0..$#lines) {
  next unless $lines[$i] =~ /addArg\s*\(/;
  next if $lines[$i] =~ /^func /;
  my $fn = "?";
